import os
import azure.cognitiveservices.speech as speechsdk

def get_speech_config():
    speech_key = os.environ.get("AZURE_SPEECH_KEY")
    service_region = os.environ.get("AZURE_SPEECH_REGION")
    if not speech_key or not service_region:
        raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION environment variables must be set.")
    return speechsdk.SpeechConfig(subscription=speech_key, region=service_region)

def get_speech_synthesizer():
    speech_config = get_speech_config()
    return speechsdk.SpeechSynthesizer(speech_config=speech_config, audio_config=None)

from dataclasses import dataclass

@dataclass
class SynthesisRequest:
    text: str
    voice_name: str = "en-US-JennyNeural"
    output_format: str = "audio-16khz-128kbitrate-mono-mp3"

@dataclass
class SynthesisSSMLRequest:
    ssml: str
    output_format: str = "audio-16khz-128kbitrate-mono-mp3"

@dataclass
class VoiceInfo:
    short_name: str
    display_name: str
    locale: str
    gender: str
    sample_rate_hertz: str
    voice_type: str

@dataclass
class TranslationRequest:
    text: str
    target_language: str
    source_language: str = "en"

@dataclass
class SafetyCheckRequest:
    text: str

@dataclass
class EmbeddingRequest:
    text: str

@dataclass
class TranscriptionRequest:
    audio_bytes: bytes
    language_code: str = "en-US"

def save_audio_to_file(audio_bytes: bytes, file_path: str):
    try:
        with open(file_path, "wb") as audio_file:
            audio_file.write(audio_bytes)
    except IOError as e:
        raise IOError(f"Error saving audio to file {file_path}: {e}")
